      count,
      locale: localeName,
      other: '$count ನಿಮಿಷಗಳ ಹಿಂದೆ',
      one: '1 ನಿಮಿಷದ ಹಿಂದೆ',
    );
    return '$_temp0';
  }

  @override
  String minutesLeft(int count) {
    String _temp0 = intl.Intl.pluralLogic(
      count,
      locale: localeName,
      other: '$count ನಿಮಿಷಗಳು ಉಳಿದಿವೆ',
      one: '1 ನಿಮಿಷ ಉಳಿದಿದೆ',
    );
    return '$_temp0';
  }

